1	-- 轨交票务清分服务建表脚本（H2 MySQL 兼容模式）
2	-- 金额单位统一为“分”，里程单位为“米”，时间均为 Asia/Shanghai 本地时间。
3	
4	CREATE TABLE IF NOT EXISTS metro_segment (
5	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
6	    line_code VARCHAR(16) NOT NULL,
