11	COMMENT ON TABLE metro_segment IS '合成里程表：线路相邻站区间里程';
12	COMMENT ON COLUMN metro_segment.line_code IS '线路编码，如 L1';
13	COMMENT ON COLUMN metro_segment.from_station IS '区间起点站编码';
14	COMMENT ON COLUMN metro_segment.to_station IS '区间终点站编码';
