43	COMMENT ON COLUMN metro_transaction.entry_station IS '进闸站编码';
44	COMMENT ON COLUMN metro_transaction.entry_time IS '进闸时间（Asia/Shanghai）';
45	COMMENT ON COLUMN metro_transaction.exit_station IS '出闸站编码，NULL 表示尚未出闸';
46	COMMENT ON COLUMN metro_transaction.exit_time IS '出闸时间（Asia/Shanghai）';
47	COMMENT ON COLUMN metro_transaction.status IS '状态：ENTERED 已进闸未出闸 / ESTIMATED 出闸缺失暂记 / COMPLETED 已出闸结算';
48	COMMENT ON COLUMN metro_transaction.distance_m IS '计费里程（米），按进出站最短路径';
49	COMMENT ON COLUMN metro_transaction.chain_base_m IS '换乘链在本程之前已累计里程（米），用于只计一次起步价';
50	COMMENT ON COLUMN metro_transaction.fare_cents IS '实收金额（分）；暂记状态下为暂记金额';
51	COMMENT ON COLUMN metro_transaction.penalty_cents IS '超时乘车补收金额（分）';
52	COMMENT ON COLUMN metro_transaction.transfer_flag IS '是否换乘接续：1 是 0 否';
53	COMMENT ON COLUMN metro_transaction.estimated_flag IS '是否暂记：1 是 0 否';
54	COMMENT ON COLUMN metro_transaction.batch_id IS '入账清分批次 ID，NULL 表示未入账';
55	COMMENT ON COLUMN metro_transaction.biz_date IS '入账业务日期';
56	COMMENT ON COLUMN metro_transaction.request_id IS '进闸请求幂等键';
57	COMMENT ON COLUMN metro_transaction.fingerprint IS '进闸请求指纹（requestId+全部业务字段）';
58	
59	CREATE TABLE IF NOT EXISTS idempotency_record (
60	    scope VARCHAR(32) NOT NULL,
61	    request_id VARCHAR(64) NOT NULL,
62	    fingerprint VARCHAR(128) NOT NULL,
63	    response_body CLOB NOT NULL,
64	    created_at DATETIME NOT NULL,
65	    PRIMARY KEY (scope, request_id)
66	);
67	COMMENT ON TABLE idempotency_record IS '幂等记录：同键同参返回首次结果，同键异参返回 409';
68	COMMENT ON COLUMN idempotency_record.scope IS '操作类型：ENTRY/EXIT/ESTIMATE/SEAL/REFUND_APPLY/REFUND_CONFIRM/CARD_CLOSE/ADJ_BATCH_OPEN/ADJ_INCLUDE/ADJ_BATCH_SEAL';
69	COMMENT ON COLUMN idempotency_record.request_id IS '请求幂等键';
70	COMMENT ON COLUMN idempotency_record.fingerprint IS '请求指纹，覆盖 requestId 与全部业务字段';
71	COMMENT ON COLUMN idempotency_record.response_body IS '首次成功响应快照（JSON）';
72	
73	CREATE TABLE IF NOT EXISTS clearing_batch (
74	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
75	    biz_date DATE NOT NULL,
76	    status VARCHAR(16) NOT NULL,
77	    total_cents BIGINT NOT NULL DEFAULT 0,
78	    txn_count INT NOT NULL DEFAULT 0,
79	    seal_request_id VARCHAR(64) NULL,
80	    created_at DATETIME NOT NULL,
81	    sealed_at DATETIME NULL,
82	    CONSTRAINT uk_biz_date UNIQUE (biz_date)
83	);
84	COMMENT ON TABLE clearing_batch IS '清分批次：按业务日期日结，封账为终态';
85	COMMENT ON COLUMN clearing_batch.biz_date IS '业务日期';
86	COMMENT ON COLUMN clearing_batch.status IS '状态：OPEN 未封账 / SEALED 已封账（终态）';
87	COMMENT ON COLUMN clearing_batch.total_cents IS '批次合计（分），封账时快照，封账后不再变化';
88	COMMENT ON COLUMN clearing_batch.txn_count IS '批次内交易笔数';
89	COMMENT ON COLUMN clearing_batch.seal_request_id IS '封账请求幂等键';
90	
91	CREATE TABLE IF NOT EXISTS clearing_detail (
92	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
93	    batch_id BIGINT NOT NULL,
94	    txn_no VARCHAR(64) NOT NULL,
95	    line_code VARCHAR(16) NOT NULL,
96	    distance_m BIGINT NOT NULL,
97	    ratio DECIMAL(10,4) NOT NULL,
98	    amount_cents BIGINT NOT NULL,
99	    entry_type VARCHAR(16) NOT NULL,
100	    created_at DATETIME NOT NULL
101	);
102	COMMENT ON TABLE clearing_detail IS '清分明细：按线路分摊，可逐笔复算';
103	COMMENT ON COLUMN clearing_detail.batch_id IS '所属清分批次 ID';
104	COMMENT ON COLUMN clearing_detail.txn_no IS '交易流水号';
105	COMMENT ON COLUMN clearing_detail.line_code IS '承运线路编码';
106	COMMENT ON COLUMN clearing_detail.distance_m IS '该线路承运里程（米）';
107	COMMENT ON COLUMN clearing_detail.ratio IS '分摊比例，保留四位小数';
108	COMMENT ON COLUMN clearing_detail.amount_cents IS '分摊金额（分），冲销记录为负数';
109	COMMENT ON COLUMN clearing_detail.entry_type IS '类型：NORMAL 正常结算 / ESTIMATE 暂记 / REVERSAL 暂记冲销 / SETTLE 补登实结';
110	
111	CREATE TABLE IF NOT EXISTS clearing_discrepancy (
112	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
113	    biz_date DATE NOT NULL,
114	    txn_no VARCHAR(64) NOT NULL,
115	    amount_cents BIGINT NOT NULL,
116	    reason VARCHAR(128) NOT NULL,
117	    created_at DATETIME NOT NULL
118	);
119	COMMENT ON TABLE clearing_discrepancy IS '对账差异登记：封账后迟到交易，不改已封账合计';
120	COMMENT ON COLUMN clearing_discrepancy.biz_date IS '交易原应入账的业务日期';
121	COMMENT ON COLUMN clearing_discrepancy.txn_no IS '交易流水号';
122	COMMENT ON COLUMN clearing_discrepancy.amount_cents IS '差异金额（分）';
123	COMMENT ON COLUMN clearing_discrepancy.reason IS '差异原因';
124	
125	-- 封账后冲正（退款）域：原流水、原清分明细与封账合计永不改写，
126	-- 退款以独立负向调整明细登记，仅占用行程可退余额。
127	CREATE TABLE IF NOT EXISTS metro_card (
128	    card_id VARCHAR(64) NOT NULL,
129	    status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',
130	    version INT NOT NULL DEFAULT 1,
131	    created_at DATETIME NOT NULL,
132	    updated_at DATETIME NOT NULL,
133	    PRIMARY KEY (card_id)
134	);
135	COMMENT ON TABLE metro_card IS '票卡主数据：ACTIVE 正常 / CLOSED 已关闭；关卡不影响已封账行程退款及其历史重放';
136	COMMENT ON COLUMN metro_card.card_id IS '票卡编号';
137	COMMENT ON COLUMN metro_card.status IS '票卡状态：ACTIVE 正常 / CLOSED 已关闭';
138	COMMENT ON COLUMN metro_card.version IS '乐观锁版本，从 1 开始，每次成功变更加 1';
139	
140	CREATE TABLE IF NOT EXISTS refund_order (
141	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
142	    refund_no VARCHAR(64) NOT NULL,
143	    txn_no VARCHAR(64) NOT NULL,
144	    amount_cents BIGINT NOT NULL,
145	    status VARCHAR(24) NOT NULL,
146	    version INT NOT NULL DEFAULT 1,
147	    first_reviewer VARCHAR(64) NULL,
148	    first_review_time DATETIME NULL,
149	    final_reviewer VARCHAR(64) NULL,
150	    confirmed_time DATETIME NULL,
151	    apply_request_id VARCHAR(64) NOT NULL,
152	    apply_time DATETIME NOT NULL,
153	    created_at DATETIME NOT NULL,
154	    updated_at DATETIME NOT NULL,
155	    CONSTRAINT uk_refund_no UNIQUE (refund_no)
156	);
157	COMMENT ON TABLE refund_order IS '退款单：仅引用已封账且已按实结算的行程；金额单位分，单次为正';
158	COMMENT ON COLUMN refund_order.refund_no IS '退款单号，全局唯一';
159	COMMENT ON COLUMN refund_order.txn_no IS '被退款的原交易流水号（COMPLETED 且原批次已封账）';
160	COMMENT ON COLUMN refund_order.amount_cents IS '本次退款金额（分），正整数；同行程累计退款不得超过原实收';
161	COMMENT ON COLUMN refund_order.status IS '状态：PENDING 待复核（0 人）/ IN_REVIEW 已一人复核 / CONFIRMED 双人确认完成';
162	COMMENT ON COLUMN refund_order.version IS '乐观锁版本，从 1 开始，每次成功变更加 1：首人复核后 2，最终确认后 3';
163	COMMENT ON COLUMN refund_order.first_reviewer IS '第一名复核人工号，NULL 表示尚无人复核';
164	COMMENT ON COLUMN refund_order.final_reviewer IS '最终（第二名，与第一人不同）复核人工号，NULL 表示未最终确认';
165	COMMENT ON COLUMN refund_order.confirmed_time IS '最终确认时刻（Asia/Shanghai），NULL 表示未确认';
166	
167	CREATE TABLE IF NOT EXISTS refund_review (
168	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
169	    refund_no VARCHAR(64) NOT NULL,
170	    reviewer VARCHAR(64) NOT NULL,
171	    review_time DATETIME NOT NULL,
172	    request_id VARCHAR(64) NOT NULL,
173	    created_at DATETIME NOT NULL,
174	    CONSTRAINT uk_refund_reviewer UNIQUE (refund_no, reviewer)
175	);
176	COMMENT ON TABLE refund_review IS '退款复核登记：同一退款单同一复核人只能登记一次，最终确认须两名不同复核人';
177	COMMENT ON COLUMN refund_review.refund_no IS '退款单号';
178	COMMENT ON COLUMN refund_review.reviewer IS '复核人工号；两名复核人必须不同';
179	COMMENT ON COLUMN refund_review.review_time IS '复核确认精确时刻（Asia/Shanghai）';
180	
181	CREATE TABLE IF NOT EXISTS refund_line_share (
182	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
183	    txn_no VARCHAR(64) NOT NULL,
184	    line_code VARCHAR(16) NOT NULL,
185	    original_share_cents BIGINT NOT NULL,
186	    refunded_cents BIGINT NOT NULL DEFAULT 0,
187	    created_at DATETIME NOT NULL,
188	    updated_at DATETIME NOT NULL,
189	    CONSTRAINT uk_txn_line_share UNIQUE (txn_no, line_code)
190	);
191	COMMENT ON TABLE refund_line_share IS '行程逐线路可退余额：原实收份额快照与累计已退占用，refunded 永不超过 original';
192	COMMENT ON COLUMN refund_line_share.original_share_cents IS '该线路在原清分明细中的实收份额（分，正数），取自封账批次 NORMAL/SETTLE 明细';
193	COMMENT ON COLUMN refund_line_share.refunded_cents IS '该线路累计已退款占用（分），并发退款下不得超过 original_share_cents';
194	
195	CREATE TABLE IF NOT EXISTS refund_adjustment (
196	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
197	    adjustment_no VARCHAR(96) NOT NULL,
198	    refund_no VARCHAR(64) NOT NULL,
199	    txn_no VARCHAR(64) NOT NULL,
200	    amount_cents BIGINT NOT NULL,
201	    batch_id BIGINT NULL,
202	    confirm_request_id VARCHAR(64) NOT NULL,
203	    created_at DATETIME NOT NULL,
204	    CONSTRAINT uk_adjustment_no UNIQUE (adjustment_no),
205	    CONSTRAINT uk_adjustment_refund UNIQUE (refund_no)
206	);
207	COMMENT ON TABLE refund_adjustment IS '退款调整单：双人确认成功后生成，独立于原清分；一张退款单至多一张调整单';
208	COMMENT ON COLUMN refund_adjustment.amount_cents IS '调整单金额（分，正数），其明细均为负向';
209	COMMENT ON COLUMN refund_adjustment.batch_id IS '纳入的调账批次 ID，NULL 表示尚未纳入；一张调整单只能纳入一个批次';
210	
211	CREATE TABLE IF NOT EXISTS refund_adjustment_detail (
212	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
213	    adjustment_id BIGINT NOT NULL,
214	    line_code VARCHAR(16) NOT NULL,
215	    amount_cents BIGINT NOT NULL,
216	    created_at DATETIME NOT NULL,
217	    CONSTRAINT uk_adjustment_line UNIQUE (adjustment_id, line_code)
218	);
219	COMMENT ON TABLE refund_adjustment_detail IS '退款负向调整明细：按原线路实收份额分摊，金额为负，合计等于退款金额的相反数';
220	COMMENT ON COLUMN refund_adjustment_detail.amount_cents IS '该线路负向调整金额（分，负数）';
221	
222	CREATE TABLE IF NOT EXISTS adjustment_batch (
223	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
224	    batch_no VARCHAR(64) NOT NULL,
225	    status VARCHAR(16) NOT NULL,
226	    total_cents BIGINT NOT NULL DEFAULT 0,
227	    adjustment_count INT NOT NULL DEFAULT 0,
228	    version INT NOT NULL DEFAULT 1,
229	    open_request_id VARCHAR(64) NOT NULL,
230	    seal_request_id VARCHAR(64) NULL,
231	    created_at DATETIME NOT NULL,
232	    sealed_at DATETIME NULL,
233	    CONSTRAINT uk_adjustment_batch_no UNIQUE (batch_no)
234	);
235	COMMENT ON TABLE adjustment_batch IS '调账批次：纳入负向调整单，封存后只读；与原日清分批次相互独立';
236	COMMENT ON COLUMN adjustment_batch.status IS '状态：OPEN 开放可纳入 / SEALED 已封存（终态，只读）';
237	COMMENT ON COLUMN adjustment_batch.total_cents IS '批次内负向调整明细合计（分，负数或 0），封存时快照';
238	COMMENT ON COLUMN adjustment_batch.adjustment_count IS '已纳入调整单数量；重复纳入不重复计额';
239	COMMENT ON COLUMN adjustment_batch.version IS '乐观锁版本，从 1 开始，每次成功变更加 1';
240	
241	CREATE TABLE IF NOT EXISTS adjustment_detail (
242	    id BIGINT AUTO_INCREMENT PRIMARY KEY,
243	    batch_id BIGINT NOT NULL,
244	    adjustment_id BIGINT NOT NULL,
245	    txn_no VARCHAR(64) NOT NULL,
246	    line_code VARCHAR(16) NOT NULL,
247	    amount_cents BIGINT NOT NULL,
248	    created_at DATETIME NOT NULL,
249	    CONSTRAINT uk_batch_adjustment_line UNIQUE (batch_id, adjustment_id, line_code)
250	);
251	COMMENT ON TABLE adjustment_detail IS '调账批次明细：调整单纳入时复制其负向明细，封存后只读';
252	COMMENT ON COLUMN adjustment_detail.amount_cents IS '负向调整金额（分，负数）';
253	
