49	/**
50	 * 封账后冲正（退款）业务服务：退款申请、双人不同复核人确认、
51	 * 按原线路实收份额分摊并占用可退余额、独立负向调整单纳入调账批次、
52	 * 批次封存与逐线路余额查询。原流水、原清分明细与封账合计永不改写。
53	 *
54	 * <p>写操作以 requestId 幂等：指纹为结构化 JSON（数组、值带类型，分隔符会被
55	 * 转义），覆盖操作域与全部业务参数（含 expectedVersion、精确时刻）；
56	 * 同键同参重放首次冻结结果，同键异参 409，业务失败回滚不占键。
57	 */
58	@Service
59	public class RefundService {
60	
61	    /** 幂等记录操作域。 */
62	    static final String SCOPE_APPLY = "REFUND_APPLY";
63	    static final String SCOPE_CONFIRM = "REFUND_CONFIRM";
64	    static final String SCOPE_CARD_CLOSE = "CARD_CLOSE";
65	    static final String SCOPE_BATCH_OPEN = "ADJ_BATCH_OPEN";
66	    static final String SCOPE_INCLUDE = "ADJ_INCLUDE";
67	    static final String SCOPE_BATCH_SEAL = "ADJ_BATCH_SEAL";
68	
69	    private final RefundRepository refundRepository;
70	    private final MetroRepository metroRepository;
71	    private final TransactionTemplate txTemplate;
72	    private final ObjectMapper objectMapper;
73	
74	    public RefundService(RefundRepository refundRepository, MetroRepository metroRepository,
75	                         PlatformTransactionManager transactionManager, ObjectMapper objectMapper) {
76	        this.refundRepository = refundRepository;
77	        this.metroRepository = metroRepository;
78	        this.txTemplate = new TransactionTemplate(transactionManager);
79	        this.objectMapper = objectMapper;
80	    }
81	
82	    /** 申请退款：校验行程已封账且已按实结算，快照逐线路原份额。 */
83	    public RefundApplyResponse apply(RefundApplyRequest request) {
84	        String fingerprint = fingerprint(SCOPE_APPLY, List.of(request.requestId(), request.refundNo(),
85	                request.txnNo(), request.amountCents(), request.applyTime().toString()));
86	        return idempotent(SCOPE_APPLY, request.requestId(), fingerprint, RefundApplyResponse.class,
87	                () -> doApply(request));
88	    }
89	
90	    /** 双人复核确认：两名不同复核人，最终确认事务内共同校验、分摊占用并生成负向调整单。 */
91	    public RefundConfirmResponse confirm(RefundConfirmRequest request) {
92	        String fingerprint = fingerprint(SCOPE_CONFIRM, List.of(request.requestId(), request.refundNo(),
93	                request.reviewer(), request.reviewTime().toString(), request.expectedVersion()));
94	        return idempotent(SCOPE_CONFIRM, request.requestId(), fingerprint, RefundConfirmResponse.class,
95	                () -> doConfirm(request));
96	    }
97	
98	    /** 开放调账批次。 */
99	    public AdjustmentBatchOpenResponse openBatch(AdjustmentBatchOpenRequest request) {
100	        String fingerprint = fingerprint(SCOPE_BATCH_OPEN,
101	                List.of(request.requestId(), request.batchNo(), request.openTime().toString()));
102	        return idempotent(SCOPE_BATCH_OPEN, request.requestId(), fingerprint,
103	                AdjustmentBatchOpenResponse.class, () -> doOpenBatch(request));
104	    }
105	
106	    /** 将调整单纳入唯一开放调账批次；重复纳入不重复计额，封存后拒绝。 */
107	    public AdjustmentIncludeResponse include(AdjustmentIncludeRequest request) {
108	        String fingerprint = fingerprint(SCOPE_INCLUDE, List.of(request.requestId(),
109	                request.adjustmentNo(), request.batchNo(), request.includeTime().toString(),
110	                request.expectedVersion()));
111	        return idempotent(SCOPE_INCLUDE, request.requestId(), fingerprint,
112	                AdjustmentIncludeResponse.class, () -> doInclude(request));
113	    }
114	
115	    /** 封存调账批次（终态，只读）。 */
116	    public AdjustmentSealResponse sealBatch(AdjustmentSealRequest request) {
117	        String fingerprint = fingerprint(SCOPE_BATCH_SEAL, List.of(request.requestId(),
118	                request.batchNo(), request.sealTime().toString(), request.expectedVersion()));
119	        return idempotent(SCOPE_BATCH_SEAL, request.requestId(), fingerprint,
120	                AdjustmentSealResponse.class, () -> doSealBatch(request));
121	    }
122	
123	    /** 查询调账批次视图。 */
124	    public AdjustmentBatchView batchView(String batchNo) {
125	        AdjustmentBatchRow batch = refundRepository.findAdjustmentBatchByNo(batchNo)
126	                .orElseThrow(() -> MetroException.notFound("ADJ_BATCH_NOT_FOUND",
127	                        "调账批次不存在: " + batchNo));
128	        List<BatchDetailRow> rows = refundRepository.findBatchDetails(batch.id());
129	        boolean sealed = "SEALED".equals(batch.status());
130	        long total = sealed ? batch.totalCents() : rows.stream().mapToLong(BatchDetailRow::amountCents).sum();
131	        int count = sealed ? batch.adjustmentCount()
132	                : refundRepository.countAdjustmentsInBatch(batch.id());
133	        List<AdjustmentBatchView.LineDetail> details = new ArrayList<>();
134	        for (BatchDetailRow row : rows) {
135	            details.add(new AdjustmentBatchView.LineDetail(row.adjustmentNo(), row.txnNo(),
136	                    row.lineCode(), row.amountCents()));
137	        }
138	        return new AdjustmentBatchView(batch.batchNo(), batch.status(), total, count, batch.version(),
139	                details);
140	    }
141	
142	    /** 查询行程逐线路可退余额。 */
143	    public RefundBalanceResponse balance(String txnNo) {
144	        TxnRow txn = metroRepository.findTxnByNo(txnNo)
145	                .orElseThrow(() -> MetroException.notFound("TXN_NOT_FOUND", "交易流水不存在: " + txnNo));
146	        List<LineShareRow> shares = refundRepository.findSharesByTxn(txnNo);
147	        long originalTotal;
148	        List<RefundBalanceResponse.LineBalance> lines = new ArrayList<>();
149	        if (shares.isEmpty()) {
150	            // 尚无退款申请：由已封账实结明细实时推导原份额，已退为 0
151	            Map<String, Long> originals = settledLineShares(txn);
152	            shares = originals.entrySet().stream()
153	                    .map(e -> new LineShareRow(0L, txnNo, e.getKey(), e.getValue(), 0L))
154	                    .toList();
155	        }
156	        long refundedTotal = 0L;
157	        for (LineShareRow share : shares) {
158	            long available = share.originalShareCents() - share.refundedCents();
159	            refundedTotal += share.refundedCents();
160	            lines.add(new RefundBalanceResponse.LineBalance(share.lineCode(),
161	                    share.originalShareCents(), share.refundedCents(), available));
162	        }
163	        originalTotal = shares.stream().mapToLong(LineShareRow::originalShareCents).sum();
164	        return new RefundBalanceResponse(txnNo, originalTotal, refundedTotal,
165	                originalTotal - refundedTotal, lines);
166	    }
167	
168	    /** 关闭原票卡：不影响已成功退款的历史重放。 */
169	    public CardCloseResponse closeCard(CardCloseRequest request) {
170	        String fingerprint = fingerprint(SCOPE_CARD_CLOSE, List.of(request.requestId(), request.cardId(),
171	                request.closeTime().toString(), request.expectedVersion()));
172	        return idempotent(SCOPE_CARD_CLOSE, request.requestId(), fingerprint, CardCloseResponse.class,
173	                () -> doCloseCard(request));
174	    }
175	
176	    // ---- 申请 ----
177	
178	    private RefundApplyResponse doApply(RefundApplyRequest request) {
179	        TxnRow txn = metroRepository.findTxnByNoForUpdate(request.txnNo())
180	                .orElseThrow(() -> MetroException.notFound("TXN_NOT_FOUND",
181	                        "交易流水不存在: " + request.txnNo()));
182	        requireSealedSettled(txn);
183	        Map<String, Long> originals = settledLineShares(txn);
184	        long originalTotal = originals.values().stream().mapToLong(Long::longValue).sum();
185	
186	        // 锁定该行程全部线路余额行（与最终确认互斥），缺失则以封账实结明细初始化快照
187	        List<LineShareRow> shares = ensureLineShares(txn.txnNo(), originals);
188	        long refundedTotal = shares.stream().mapToLong(LineShareRow::refundedCents).sum();
189	        long available = originalTotal - refundedTotal;
190	        if (request.amountCents() > available) {
191	            throw MetroException.unprocessable("REFUND_EXCEEDS_AVAILABLE",
192	                    "退款金额超过行程可退余额：申请 " + request.amountCents() + " 分，可退 " + available + " 分");
193	        }
194	
195	        refundRepository.insertCardIfAbsent(txn.cardId(), LocalDateTime.now());        try {
196	            refundRepository.insertRefundOrder(new RefundOrderRow(0L, request.refundNo(),
197	                    request.txnNo(), request.amountCents(), "PENDING", 1, null, null, null, null,
198	                    request.requestId(), request.applyTime()));
199	        } catch (DuplicateKeyException ex) {
200	            throw MetroException.conflict("DUPLICATE_REFUND_NO", "退款单号重复: " + request.refundNo());
201	        }
202	        return new RefundApplyResponse(request.refundNo(), request.txnNo(), request.amountCents(),
203	                "PENDING", 1, false);
204	    }
205	
206	    // ---- 双人确认 ----
207	
208	    private RefundConfirmResponse doConfirm(RefundConfirmRequest request) {
209	        RefundOrderRow refund = refundRepository.findRefundByNoForUpdate(request.refundNo())
210	                .orElseThrow(() -> MetroException.notFound("REFUND_NOT_FOUND",
211	                        "退款单不存在: " + request.refundNo()));
212	        if ("CONFIRMED".equals(refund.status())) {
213	            if (request.expectedVersion() != refund.version()) {
214	                throw versionConflict(request.expectedVersion(), refund.version());
215	            }
216	            throw MetroException.unprocessable("REFUND_ALREADY_CONFIRMED",
217	                    "退款单已完成双人确认: " + request.refundNo());
218	        }
219	
220	        List<ReviewRow> reviews = refundRepository.findReviewsForUpdate(request.refundNo());
221	        if ("PENDING".equals(refund.status())) {
222	            if (request.expectedVersion() != 1) {
223	                throw versionConflict(request.expectedVersion(), refund.version());
224	            }
225	            // 首人复核：登记后单人不生效，等待不同的第二人
226	            if (reviews.stream().anyMatch(r -> r.reviewer().equals(request.reviewer()))) {
227	                throw MetroException.unprocessable("REVIEWER_DUPLICATE",
228	                        "同一复核人不能重复复核: " + request.reviewer());
229	            }
230	            insertReviewOrConflict(request);
231	            if (!refundRepository.markFirstReview(request.refundNo(), request.reviewer(),
232	                    request.reviewTime())) {
233	                throw new IllegalStateException("首人复核状态变更失败: " + request.refundNo());
234	            }
235	            return new RefundConfirmResponse(request.refundNo(), null, refund.txnNo(),
236	                    refund.amountCents(), "IN_REVIEW", 2, request.reviewer(), null, false,
237	                    List.of(), false);
238	        }
239	
240	        // IN_REVIEW：最终确认。版本必须为 2，且两名复核人在本事务内共同校验为不同两人
241	        if (request.expectedVersion() != 2) {
242	            throw versionConflict(request.expectedVersion(), refund.version());
243	        }
244	        if (refund.firstReviewer() != null && refund.firstReviewer().equals(request.reviewer())) {
245	            throw MetroException.unprocessable("REVIEWER_MUST_DIFFER",
246	                    "最终确认人必须与首人复核不同，单人确认不生效");
247	        }
248	        insertReviewOrConflict(request);
249	        List<ReviewRow> committedReviews = refundRepository.findReviewsForUpdate(request.refundNo());
250	        long distinctReviewers = committedReviews.stream().map(ReviewRow::reviewer).distinct().count();
251	        if (committedReviews.size() < 2 || distinctReviewers < 2) {
252	            throw MetroException.unprocessable("REVIEWERS_INSUFFICIENT",
253	                    "最终确认须两名不同复核人共同校验");
254	        }
255	
256	        // 分摊并逐线路占用可退余额（行已锁，条件 UPDATE 兜底，并发退款不得超退）
257	        List<LineShareRow> shares = refundRepository.findSharesByTxnForUpdate(refund.txnNo());
258	        Map<String, Long> allocation = allocateRefund(shares, refund.amountCents());
259	        for (Map.Entry<String, Long> entry : allocation.entrySet()) {
260	            int updated = refundRepository.occupyLineShare(refund.txnNo(), entry.getKey(),
261	                    entry.getValue());
262	            if (updated != 1) {
263	                throw MetroException.unprocessable("REFUND_EXCEEDS_AVAILABLE",
264	                        "线路 " + entry.getKey() + " 可退余额不足，并发退款拒绝超退");
265	            }
266	        }
267	
268	        if (!refundRepository.markConfirmed(request.refundNo(), request.reviewer(),
269	                request.reviewTime())) {
270	            throw new IllegalStateException("最终确认状态变更失败: " + request.refundNo());
271	        }
272	        String adjustmentNo = "ADJ-" + request.refundNo();
273	        long adjustmentId;
274	        try {
275	            adjustmentId = refundRepository.insertAdjustment(adjustmentNo, request.refundNo(),
276	                    refund.txnNo(), refund.amountCents(), request.requestId());
277	        } catch (DuplicateKeyException ex) {
278	            throw new IllegalStateException("调整单重复生成: " + adjustmentNo, ex);
279	        }
280	        List<RefundConfirmResponse.LineAllocation> allocations = new ArrayList<>();
281	        for (LineShareRow share : shares) {
282	            long lineRefund = allocation.getOrDefault(share.lineCode(), 0L);
283	            if (lineRefund <= 0) {
284	                continue;
285	            }
286	            refundRepository.insertAdjustmentDetail(adjustmentId, share.lineCode(), -lineRefund);
287	            allocations.add(new RefundConfirmResponse.LineAllocation(share.lineCode(), lineRefund));
288	        }
289	        long allocatedTotal = allocations.stream()
290	                .mapToLong(RefundConfirmResponse.LineAllocation::refundCents).sum();
291	        if (allocatedTotal != refund.amountCents()) {
292	            throw new IllegalStateException("退款分摊合计不等于退款金额");
293	        }
294	        return new RefundConfirmResponse(request.refundNo(), adjustmentNo, refund.txnNo(),
295	                refund.amountCents(), "CONFIRMED", 3, refund.firstReviewer(), request.reviewer(),
296	                true, allocations, false);
297	    }
298	
299	    /**
300	     * 按每条原线路实收份额分摊本次退款：各线路先按原份额比例向下取整并限制到
301	     * 可退余额，剩余分逐一分给尚有可退余额的线路，按原份额降序、线路编号升序
302	     * 循环；合计等于退款金额，且各线路累计不超原份额。
303	     */
304	    static Map<String, Long> allocateRefund(List<LineShareRow> shares, long refundCents) {
305	        long totalOriginal = shares.stream().mapToLong(LineShareRow::originalShareCents).sum();
306	        long totalAvailable = shares.stream()
307	                .mapToLong(s -> s.originalShareCents() - s.refundedCents()).sum();
308	        if (totalOriginal <= 0 || refundCents > totalAvailable) {
309	            throw MetroException.unprocessable("REFUND_EXCEEDS_AVAILABLE",
310	                    "可退余额不足：退款 " + refundCents + " 分，可退 " + totalAvailable + " 分");
311	        }
312	        Map<String, Long> allocated = new LinkedHashMap<>();
313	        long assigned = 0L;
314	        for (LineShareRow share : shares) {
315	            long available = share.originalShareCents() - share.refundedCents();
316	            long floor = refundCents * share.originalShareCents() / totalOriginal;
317	            long value = Math.min(available, floor);
318	            allocated.put(share.lineCode(), value);
319	            assigned += value;
320	        }
321	        long remainder = refundCents - assigned;
322	        List<String> cyclicOrder = shares.stream()
323	                .sorted(Comparator.comparingLong(LineShareRow::originalShareCents).reversed()
324	                        .thenComparing(LineShareRow::lineCode))
325	                .map(LineShareRow::lineCode)
326	                .toList();
327	        int cursor = 0;
328	        int guard = 0;
329	        while (remainder > 0) {
330	            if (++guard > cyclicOrder.size() * (refundCents + 1)) {
331	                throw new IllegalStateException("退款尾差分摊无法收敛");
332	            }
333	            String line = cyclicOrder.get(cursor % cyclicOrder.size());
334	            cursor++;
335	            LineShareRow share = shares.stream().filter(s -> s.lineCode().equals(line)).findFirst()
336	                    .orElseThrow();
337	            long available = share.originalShareCents() - share.refundedCents()
338	                    - allocated.get(line);
339	            if (available > 0) {
340	                allocated.merge(line, 1L, Long::sum);
341	                remainder--;
342	            }
343	        }
344	        return allocated;
345	    }
