347	    // ---- 调账批次 ----
348	
349	    private AdjustmentBatchOpenResponse doOpenBatch(AdjustmentBatchOpenRequest request) {
350	        if (refundRepository.findAdjustmentBatchByNo(request.batchNo()).isPresent()) {
351	            throw MetroException.conflict("DUPLICATE_ADJ_BATCH_NO",
352	                    "调账批次号重复: " + request.batchNo());
353	        }
354	        try {
355	            refundRepository.insertAdjustmentBatch(request.batchNo(), request.requestId(),
356	                    request.openTime());
357	        } catch (DuplicateKeyException ex) {
358	            throw MetroException.conflict("DUPLICATE_ADJ_BATCH_NO",
359	                    "调账批次号重复: " + request.batchNo());
360	        }
361	        return new AdjustmentBatchOpenResponse(request.batchNo(), "OPEN", 1, false);
362	    }
363	
364	    private AdjustmentIncludeResponse doInclude(AdjustmentIncludeRequest request) {
365	        AdjustmentRow adjustment = refundRepository.findAdjustmentByNoForUpdate(request.adjustmentNo())
366	                .orElseThrow(() -> MetroException.notFound("ADJUSTMENT_NOT_FOUND",
367	                        "调整单不存在: " + request.adjustmentNo()));
368	        if (adjustment.batchId() != null) {
369	            AdjustmentBatchRow existing = refundRepository.findAdjustmentBatchById(adjustment.batchId())
370	                    .orElseThrow(() -> new IllegalStateException("调整单所属批次缺失"));
371	            if (!existing.batchNo().equals(request.batchNo())) {
372	                throw MetroException.unprocessable("ADJUSTMENT_ALREADY_IN_BATCH",
373	                        "调整单只能纳入一个批次，已纳入: " + existing.batchNo());
374	            }
375	            if ("SEALED".equals(existing.status())) {
376	                throw MetroException.unprocessable("ADJ_BATCH_SEALED",
377	                        "调账批次已封存，只读不可纳入: " + existing.batchNo());
378	            }
379	            // 重复纳入同一开放批次：幂等成功，不重复计额
380	            return new AdjustmentIncludeResponse(request.adjustmentNo(), request.batchNo(),
381	                    existing.status(), existing.version(), true, false);
382	        }
383	        AdjustmentBatchRow batch = refundRepository.findAdjustmentBatchByNoForUpdate(request.batchNo())
384	                .orElseThrow(() -> MetroException.notFound("ADJ_BATCH_NOT_FOUND",
385	                        "调账批次不存在: " + request.batchNo()));
386	        if ("SEALED".equals(batch.status())) {
387	            throw MetroException.unprocessable("ADJ_BATCH_SEALED",
388	                    "调账批次已封存，只读不可纳入: " + request.batchNo());
389	        }
390	        if (request.expectedVersion() != batch.version()) {
391	            throw versionConflict(request.expectedVersion(), batch.version());
392	        }
393	        int assigned = refundRepository.assignAdjustmentBatch(adjustment.id(), batch.id());
394	        if (assigned != 1) {
395	            throw new IllegalStateException("调整单纳入批次状态变更失败");
396	        }
397	        List<AdjustmentDetailRow> details = refundRepository.findAdjustmentDetails(adjustment.id());
398	        try {
399	            for (AdjustmentDetailRow detail : details) {
400	                refundRepository.insertBatchDetail(batch.id(), adjustment.id(), adjustment.txnNo(),
401	                        detail.lineCode(), detail.amountCents());
402	            }
403	        } catch (DuplicateKeyException ex) {
404	            // 唯一约束兜底：重复纳入不重复计额
405	            return new AdjustmentIncludeResponse(request.adjustmentNo(), request.batchNo(), "OPEN",
406	                    batch.version(), true, false);
407	        }
408	        if (!refundRepository.incrementBatchAfterInclude(batch.id(), batch.version())) {
409	            throw new IllegalStateException("批次版本变更失败");
410	        }
411	        return new AdjustmentIncludeResponse(request.adjustmentNo(), request.batchNo(), "OPEN",
412	                batch.version() + 1, false, false);
413	    }
414	
415	    private AdjustmentSealResponse doSealBatch(AdjustmentSealRequest request) {
416	        AdjustmentBatchRow batch = refundRepository.findAdjustmentBatchByNoForUpdate(request.batchNo())
417	                .orElseThrow(() -> MetroException.notFound("ADJ_BATCH_NOT_FOUND",
418	                        "调账批次不存在: " + request.batchNo()));
419	        if ("SEALED".equals(batch.status())) {
420	            // 封存为终态：重复封存幂等成功，只读快照不变
421	            return new AdjustmentSealResponse(batch.batchNo(), "SEALED", batch.totalCents(),
422	                    batch.adjustmentCount(), batch.version(), true);
423	        }
424	        if (request.expectedVersion() != batch.version()) {
425	            throw versionConflict(request.expectedVersion(), batch.version());
426	        }
427	        long total = refundRepository.findBatchDetails(batch.id()).stream()
428	                .mapToLong(BatchDetailRow::amountCents).sum();
429	        int count = refundRepository.countAdjustmentsInBatch(batch.id());
430	        if (!refundRepository.sealAdjustmentBatch(batch.id(), total, count, request.requestId(),
431	                request.sealTime(), batch.version())) {
432	            // 并发封存：胜出方已置终态，重读后按终态幂等返回
433	            AdjustmentBatchRow latest = refundRepository.findAdjustmentBatchByNo(request.batchNo())
434	                    .orElseThrow(() -> new IllegalStateException("调账批次丢失: " + request.batchNo()));
435	            if ("SEALED".equals(latest.status())) {
436	                return new AdjustmentSealResponse(latest.batchNo(), "SEALED", latest.totalCents(),
437	                        latest.adjustmentCount(), latest.version(), true);
438	            }
439	            throw new IllegalStateException("调账批次封存失败: " + request.batchNo());
440	        }
441	        return new AdjustmentSealResponse(batch.batchNo(), "SEALED", total, count,
442	                batch.version() + 1, false);
443	    }
