445	    // ---- 票卡 ----
446	
447	    private CardCloseResponse doCloseCard(CardCloseRequest request) {
448	        CardRow card = refundRepository.findCardForUpdate(request.cardId())
449	                .orElseThrow(() -> MetroException.notFound("CARD_NOT_FOUND",
450	                        "票卡不存在: " + request.cardId()));
451	        if (request.expectedVersion() != card.version()) {
452	            throw versionConflict(request.expectedVersion(), card.version());
453	        }
454	        if ("CLOSED".equals(card.status())) {
455	            // 已关闭终态：版本匹配时幂等返回，不重复变更
456	            return new CardCloseResponse(request.cardId(), "CLOSED", card.version(), true);
457	        }
458	        if (!refundRepository.closeCard(request.cardId(), card.version(), request.closeTime())) {
459	            throw versionConflict(request.expectedVersion(), card.version());
460	        }
461	        return new CardCloseResponse(request.cardId(), "CLOSED", card.version() + 1, false);
462	    }
463	
464	    // ---- 共享校验与工具 ----
465	
466	    /** 校验行程已按实结算且所属原清分批次已封账；未出闸/暂记一律拒绝。 */
467	    private void requireSealedSettled(TxnRow txn) {
468	        if (!"COMPLETED".equals(txn.status()) || txn.batchId() == null || txn.fareCents() == null) {
469	            throw MetroException.unprocessable("REFUND_TXN_NOT_SETTLED",
470	                    "仅已出闸按实结算的行程可退款，不能处理未出闸暂记: " + txn.txnNo());
471	        }
472	        BatchRow batch = metroRepository.findBatchById(txn.batchId())
473	                .orElseThrow(() -> new IllegalStateException("行程所属清分批次缺失: " + txn.batchId()));
474	        if (!"SEALED".equals(batch.status())) {
475	            throw MetroException.unprocessable("REFUND_BATCH_NOT_SEALED",
476	                    "原清分批次尚未封账，不可退款: " + batch.bizDate());
477	        }
478	    }
479	
480	    /**
481	     * 取行程在已封账批次中的按实结算逐线路实收份额：NORMAL（正常结算）与
482	     * SETTLE（暂记后补登实结）为正向原账；ESTIMATE/REVERSAL 不计入原实收。
483	     */
484	    private Map<String, Long> settledLineShares(TxnRow txn) {
485	        if (txn.batchId() == null) {
486	            throw MetroException.unprocessable("REFUND_TXN_NOT_SETTLED",
487	                    "行程未入账，不可退款: " + txn.txnNo());
488	        }
489	        Map<String, Long> shares = new LinkedHashMap<>();
490	        for (DetailRow detail : metroRepository.findDetailsByBatch(txn.batchId())) {
491	            if (!detail.txnNo().equals(txn.txnNo())) {
492	                continue;
493	            }
494	            if ("NORMAL".equals(detail.entryType()) || "SETTLE".equals(detail.entryType())) {
495	                shares.merge(detail.lineCode(), detail.amountCents(), Long::sum);
496	            }
497	        }
498	        if (shares.isEmpty() || shares.values().stream().anyMatch(v -> v <= 0)) {
499	            throw MetroException.unprocessable("REFUND_TXN_NOT_SETTLED",
500	                    "原清分明细中无按实结算正向份额: " + txn.txnNo());
501	        }
502	        return shares;
503	    }
504	
505	    /** 确保行程逐线路份额快照存在（首次退款申请时按封账明细初始化），并加锁返回。 */
506	    private List<LineShareRow> ensureLineShares(String txnNo, Map<String, Long> originals) {
507	        List<LineShareRow> existing = refundRepository.findSharesByTxnForUpdate(txnNo);
508	        if (!existing.isEmpty()) {
509	            return existing;
510	        }
511	        originals.forEach((line, share) -> {
512	            try {
513	                refundRepository.insertLineShare(txnNo, line, share);
514	            } catch (DuplicateKeyException ex) {
515	                // 并发首次申请：唯一约束兜底，以已有快照为准
516	            }
517	        });
518	        return refundRepository.findSharesByTxnForUpdate(txnNo);
519	    }
