526	    /** 插入复核登记；同退款单同复核人唯一约束冲突时转换为 422。 */
527	    private void insertReviewOrConflict(RefundConfirmRequest request) {
528	        try {
529	            refundRepository.insertReview(request.refundNo(), request.reviewer(),
530	                    request.reviewTime(), request.requestId());
531	        } catch (DuplicateKeyException ex) {
532	            throw MetroException.unprocessable("REVIEWER_DUPLICATE",
533	                    "同一复核人不能重复复核: " + request.reviewer());
534	        }
535	    }
536	
537	    private <T extends ReplayableResponse<T>> T idempotent(String scope, String requestId,
538	                                                           String fingerprint, Class<T> type,
539	                                                           Supplier<T> action) {
540	        Optional<IdemRow> existing = metroRepository.findIdem(scope, requestId);
541	        if (existing.isPresent()) {
542	            return replay(existing.get(), fingerprint, type);
543	        }
544	        try {
545	            return txTemplate.execute(status -> {
546	                // 事务开头占位：并发同键在此阻塞或冲突，随后走重放路径；失败回滚不占键
547	                metroRepository.insertIdemPlaceholder(scope, requestId, fingerprint);
548	                T response = action.get();
549	                metroRepository.updateIdemResponse(scope, requestId, toJson(response));
550	                return response;
551	            });
552	        } catch (DuplicateKeyException ex) {
553	            return metroRepository.findIdem(scope, requestId)
554	                    .map(row -> replay(row, fingerprint, type))
555	                    .orElseThrow(() -> ex);
556	        }
557	    }
558	
559	    private <T extends ReplayableResponse<T>> T replay(IdemRow row, String fingerprint, Class<T> type) {
560	        if (!row.fingerprint().equals(fingerprint)) {
561	            throw MetroException.conflict("IDEMPOTENCY_CONFLICT",
562	                    "相同 requestId 但业务参数不一致，拒绝重复写操作");
563	        }
564	        try {
565	            return objectMapper.readValue(row.responseBody(), type).asReplayed();
566	        } catch (JsonProcessingException ex) {
567	            throw new IllegalStateException("幂等响应反序列化失败", ex);
568	        }
569	    }
570	
571	    private String toJson(Object response) {
572	        try {
573	            return objectMapper.writeValueAsString(response);
574	        } catch (JsonProcessingException ex) {
575	            throw new IllegalStateException("幂等响应序列化失败", ex);
576	        }
577	    }
578	
579	    /**
580	     * 结构化指纹：将操作域与全部参数序列化为定长 JSON 数组后取 SHA-256。
581	     * JSON 转义保证含分隔符的合法文本也无法伪造字段边界，数值保持数值类型。
582	     */
583	    private String fingerprint(String scope, List<Object> parts) {
584	        List<Object> structured = new ArrayList<>();
585	        structured.add(scope);
586	        structured.addAll(parts);
587	        String json;
588	        try {
589	            json = objectMapper.writeValueAsString(structured);
590	        } catch (JsonProcessingException ex) {
591	            throw new IllegalStateException("指纹序列化失败", ex);
592	        }
593	        try {
594	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
595	            byte[] hash = digest.digest(json.getBytes(StandardCharsets.UTF_8));
596	            StringBuilder hex = new StringBuilder(hash.length * 2);
597	            for (byte b : hash) {
598	                hex.append(Character.forDigit((b >> 4) & 0xF, 16));
599	                hex.append(Character.forDigit(b & 0xF, 16));
600	            }
601	            return hex.toString();
602	        } catch (NoSuchAlgorithmException ex) {
603	            throw new IllegalStateException("SHA-256 不可用", ex);
604	        }
605	    }
606	}
