57	    private void sealedTripAF(String requestPrefix, String txnNo, String cardId) throws Exception {
58	        postJson("/api/metro/entry",
59	                ("{\"requestId\":\"%s-e\",\"txnNo\":\"%s\",\"cardId\":\"%s\",\"station\":\"A\","
60	                        + "\"entryTime\":\"2026-09-25T09:00:00\"}").formatted(requestPrefix, txnNo, cardId),
61	                200);
62	        JsonNode exit = postJson("/api/metro/exit",
63	                ("{\"requestId\":\"%s-x\",\"txnNo\":\"%s\",\"station\":\"F\","
64	                        + "\"exitTime\":\"2026-09-25T09:40:00\"}").formatted(requestPrefix, txnNo), 200);
65	        assertEquals(500L, exit.get("fareCents").asLong());
