93	    @Test
94	    void applyTwoReviewersConfirmAllocateIncludeSealAndOriginalBooksUntouched() throws Exception {
95	        sealedTripAF("t1", "T1", "CARD1");
96	
97	        // 退款前余额查询：由封账实结明细推导
98	        JsonNode balanceBefore = getJson("/api/metro/refunds/balance/T1", 200);
99	        assertEquals(500L, balanceBefore.get("originalFareCents").asLong());
100	        assertEquals(0L, balanceBefore.get("refundedCents").asLong());
101	        assertEquals(500L, balanceBefore.get("availableCents").asLong());
102	
103	        // 申请退款 100 分
104	        JsonNode apply = postJson("/api/metro/refunds/apply", applyBody("ra1", "R1", "T1", 100), 200);
105	        assertEquals("PENDING", apply.get("status").asText());
106	        assertEquals(1, apply.get("version").asInt());
107	
108	        // 首人复核：版本 1 -> 2，单人不生效（无调整单）
109	        JsonNode first = postJson("/api/metro/refunds/confirm",
110	                confirmBody("rc1a", "R1", "U1", "2026-09-26T11:00:00", 1), 200);
111	        assertEquals("IN_REVIEW", first.get("status").asText());
112	        assertEquals(2, first.get("version").asInt());
113	        assertFalse(first.get("confirmed").asBoolean());
114	        assertTrue(first.get("adjustmentNo").isNull());
115	        assertEquals(0, jdbcTemplate.queryForObject(
116	                "SELECT COUNT(*) FROM refund_adjustment", Integer.class));
117	
118	        // 最终确认：不同复核人，版本 2 -> 3，分摊 L1=37、L2=63（尾差按份额降序给 L2）
119	        JsonNode confirmed = postJson("/api/metro/refunds/confirm",
120	                confirmBody("rc1b", "R1", "U2", "2026-09-26T11:05:00", 2), 200);
121	        assertEquals("CONFIRMED", confirmed.get("status").asText());
122	        assertEquals(3, confirmed.get("version").asInt());
123	        assertTrue(confirmed.get("confirmed").asBoolean());
124	        assertEquals("ADJ-R1", confirmed.get("adjustmentNo").asText());
125	        assertEquals("U1", confirmed.get("firstReviewer").asText());
126	        assertEquals("U2", confirmed.get("finalReviewer").asText());
127	        JsonNode allocations = confirmed.get("allocations");
128	        long allocSum = 0;
129	        for (JsonNode a : allocations) {
130	            allocSum += a.get("refundCents").asLong();
131	            if ("L1".equals(a.get("lineCode").asText())) {
132	                assertEquals(37L, a.get("refundCents").asLong());
133	            } else {
134	                assertEquals("L2", a.get("lineCode").asText());
135	                assertEquals(63L, a.get("refundCents").asLong());
136	            }
