146	        JsonNode balance = getJson("/api/metro/refunds/balance/T1", 200);
147	        assertEquals(500L, balance.get("originalFareCents").asLong());
148	        assertEquals(100L, balance.get("refundedCents").asLong());
149	        assertEquals(400L, balance.get("availableCents").asLong());
150	        for (JsonNode line : balance.get("lines")) {
151	            switch (line.get("lineCode").asText()) {
152	                case "L1" -> {
153	                    assertEquals(188L, line.get("originalShareCents").asLong());
154	                    assertEquals(37L, line.get("refundedCents").asLong());
155	                    assertEquals(151L, line.get("availableCents").asLong());
156	                }
157	                case "L2" -> {
158	                    assertEquals(312L, line.get("originalShareCents").asLong());
159	                    assertEquals(63L, line.get("refundedCents").asLong());
160	                    assertEquals(249L, line.get("availableCents").asLong());
161	                }
162	                default -> throw new IllegalStateException("unexpected line");
163	            }
164	        }
165	
