167	        JsonNode opened = postJson("/api/metro/refunds/batches/open",
168	                "{\"requestId\":\"ro1\",\"batchNo\":\"AB1\",\"openTime\":\"2026-09-26T12:00:00\"}", 200);
169	        assertEquals("OPEN", opened.get("status").asText());
170	        assertEquals(1, opened.get("version").asInt());
171	        JsonNode included = postJson("/api/metro/refunds/batches/include",
172	                "{\"requestId\":\"ri1\",\"adjustmentNo\":\"ADJ-R1\",\"batchNo\":\"AB1\","
173	                        + "\"includeTime\":\"2026-09-26T12:05:00\",\"expectedVersion\":1}", 200);
174	        assertFalse(included.get("alreadyIncluded").asBoolean());
175	        assertEquals(2, included.get("version").asInt());
176	        JsonNode reincluded = postJson("/api/metro/refunds/batches/include",
177	                "{\"requestId\":\"ri1\",\"adjustmentNo\":\"ADJ-R1\",\"batchNo\":\"AB1\","
178	                        + "\"includeTime\":\"2026-09-26T12:05:00\",\"expectedVersion\":1}", 200);
179	        assertTrue(reincluded.get("replayed").asBoolean());
180	        assertEquals(2, reincluded.get("version").asInt());
