182	        // 封存：合计 -100，调整单 1
183	        JsonNode sealed = postJson("/api/metro/refunds/batches/seal",
184	                "{\"requestId\":\"rs1\",\"batchNo\":\"AB1\",\"sealTime\":\"2026-09-26T13:00:00\","
185	                        + "\"expectedVersion\":2}", 200);
186	        assertEquals("SEALED", sealed.get("status").asText());
187	        assertEquals(-100L, sealed.get("totalCents").asLong());
