        postJson("/api/metro/refunds/batches/open",
                "{\"requestId\":\"ro9\",\"batchNo\":\"AB9\",\"openTime\":\"2026-09-26T12:00:00\"}", 200);
        JsonNode wrongIncludeVersion = postJson("/api/metro/refunds/batches/include",
