    public void insertReceiptLine(long receiptId, String lineCode, long amountCents) {
        jdbcTemplate.update(
                "INSERT INTO remittance_receipt_line (receipt_id, line_code, amount_cents, created_at)"
                        + " VALUES (?,?,?,?)",
